ion before changing it\\\" }));\\n    return jobs.map((job) => response(job, {\\n      action: \\\"edit\\\",\\n      args: { path: \\\"calc.mjs\\\", blocks: \\\"<<<<<<< SEARCH\\\\nexport const add = (a, b) => a - b;\\\\n=======\\\\nexport const add = (a, b) => a + b;\\\\n>>>>>>> REPLACE\\\" },\\n      reason: \\\"replace subtraction with the required addition\\\",\\n    }));\\n  };\\n  const result = await runMission({\\n    id: \\\"urn:test:mission:addition\\\",\\n    objective: \\\"Repair the add function so the declared test passes.\\\",\\n    territory,\\n    verifyCommand: \\\"node --test calc.test.mjs\\\",\\n    actors: 2,\\n    maxRounds: 3,\\n    apply: true,\\n  }, { dispatch, ledgerRoot });\\n\\n  assert.equal(result.outcome.verified, true);\\n  assert.equal(result.outcome.integrated, true);\\n  assert.equal(result.metrics.directInteractiveModelCalls, 0);\\n  assert.ok(result.metrics.usefulCompletions >= 2 && result.metrics.usefulCompletions <= 4);\\n  assert.match(readFileSync(join(territory, \\\"calc.mjs\\\"), \\\"utf8\\\"), /a \\\\+ b/);\\n  assert.equal(existsSync(result.ledgerPath), true);\\n  assert.equal(recallTrajectories(\\\"repair addition function\\\", { ledgerRoot })[0].changedPaths[0], \\\"calc.mjs\\\");\\n});\\n\\ntest(\\\"a concurrently changed source is certified as a protected border and not overwritten\\\", async () => {\\n  const territory = fixture(), ledgerRoot = join(territory, \\\"trajectory-ledger\\\");\\n  let wave = 0;\\n  const dispatch = async (jobs) => {\\n    wave += 1;\\n    if (wave === 1) return jobs.map((job) => response(job, { action: \\\"read\\\", args: { path: \\\"calc.mjs\\\" }, reason: \\\"inspect current source before editing\\\" }));\\n    writeFileSync(join(territory, \\\"calc.mjs\\\"), \\\"export const add = (a, b) => Number(a) + Number(b);\\\\n\\\");\\n    return jobs.map((job) => response(job, {\\n      action: \\\"edit\\\",\\n      args: { path: \\\"calc.mjs\\\", blocks: \\\"<<<<<<< SEARCH\\\\nexport const add 